/**
 * Reads files at an exact commit with `git cat-file`, never from a worktree. A readable commit
 * without the path is `absent`, which is evidence; a repository or commit that cannot be read is
 * `unavailable`, which makes the question that needed it wait.
 */
export function createGitRepositoryReader(git: Git = spawnGit): RepositoryReader {
  const hasCommit = async (repository_path: string, commit_sha: string): Promise<boolean> =>
    COMMIT.test(commit_sha) && (await git(repository_path, ["cat-file", "-e", `${commit_sha}^{commit}`]))?.code === 0;
  return {
    hasCommit,
    async readFile({ repository_path, commit_sha, path }: RepositoryFileRequest): Promise<RepositoryFile> {
      if (!await hasCommit(repository_path, commit_sha))
        return { state: "unavailable", detail: `commit ${commit_sha} is not readable in ${repository_path}` };
      if (!isTreePath(path)) return { state: "absent" };
      const object = `${commit_sha}:${path}`;
      const kind = await git(repository_path, ["cat-file", "-t", object]);
      if (!kind) return { state: "unavailable", detail: "git could not be run" };
      if (kind.code !== 0) return { state: "absent" };
      const content = await git(repository_path, ["cat-file", "-p", object]);
      return content?.code === 0 ? { state: "present", content: content.stdout }
        : { state: "unavailable", detail: content?.stderr.trim() || "git could not be run" };

async function citationEvidence(artifact: SourceArtifact, revision: CapturedRevision, sources: CapturedSources): Promise<CitationEvidence> {
  const citations = citationsOf(artifact.selected_value);
  const parsed = citations.map((citation) => ({ citation, address: citation.kind === "file" ? parseFileCitation(citation.ref) : null }));
  if (!parsed.some(({ address }) => address)) return { references: citations.map((citation, index) => reported(`citation:${index}`, citation, artifact)) };
  const head_sha = objectOf(revision.body)?.head_sha;
  if (typeof head_sha !== "string" || head_sha.length === 0)
    return { waiting: notReady("commit_unavailable", `revision ${revision.revision_id} names no head_sha for its file citations`) };
  const repository = await repositoryAt(sources, head_sha);
  if (!repository) return { waiting: notReady("repository_unavailable", `no launch repository holds commit ${head_sha}`) };
  const references: EvidenceReference[] = [];
  for (const [index, { citation, address }] of parsed.entries()) {
    const ref = `citation:${index}`;
    if (!address) { references.push(reported(ref, citation, artifact)); continue; }
    const file = await sources.repository.readFile({ repository_path: repository.repository_path, commit_sha: head_sha, path: address.path });
    if (file.state === "unavailable") return { waiting: notReady("repository_unavailable", file.detail) };
    const located: Omit<RepositoryEvidence, "content" | "is_absent"> = { source: "repository", ref,
      repository_key: repository.repository_key, commit_sha: head_sha, path: address.path, line_range: address.line_range };
    references.push(file.state === "absent" ? { ...located, is_absent: true, content: null }
      : { ...located, is_absent: false, content: lines(file.content, address.line_range) });
  }
  return { references };

test("a file is read at head_sha from the repository holding it, keeping its range", async () => {
  const source = sources();
  const result = await oakridgeEvidence.collect(finding([{ kind: "file", ref: "src/alpha.ts:2-3" }]), key(EVIDENCE_SUPPORT_ID), source);
  expect(source.paths).toEqual([`/repos/oakridge@${HEAD}:src/alpha.ts`]);
  expect(result).toMatchObject({ state: "ready", references: [{ ref: "subject" }, { source: "repository", ref: "citation:0", repository_key: "oakridge",
    commit_sha: HEAD, path: "src/alpha.ts", line_range: { start: 2, end: 3 }, is_absent: false, content: "two\nthree" }] });
});

test("a file missing at an accessible commit is evidence; an unreadable repository waits", async () => {
  const cited = finding([{ kind: "file", ref: "src/gone.ts" }]);
  expect(await oakridgeEvidence.collect(cited, key(EVIDENCE_SUPPORT_ID), sources({ file: { state: "absent" } })))
    .toMatchObject({ state: "ready", references: [{ ref: "subject" }, { source: "repository", path: "src/gone.ts", is_absent: true, content: null }] });
  expect(await oakridgeEvidence.collect(cited, key(EVIDENCE_SUPPORT_ID), sources({ commit_in: null })))
    .toMatchObject({ state: "not_ready", reason: { code: "repository_unavailable" } });
  expect(await oakridgeEvidence.collect(cited, key(EVIDENCE_SUPPORT_ID), sources({ file: { state: "unavailable", detail: "git failed" } })))
    .toMatchObject({ state: "not_ready", reason: { code: "repository_unavailable", detail: "git failed" } });

