  const configuration = parseGraderConfiguration(graders);
  if (!configuration.ok) return startupError(configuration.error.kind, configuration.error.entity_id, configuration.error.detail);
  const registration = planRegistration(configuration.value, profile.questions);
  if (!registration.ok) return startupError(registration.error.kind, registration.error.entity_id, registration.error.detail);
  const credentials = requireRunnerCredentials(selectedRunners(configuration.value), env);
  if (!credentials.ok) return startupError(credentials.error.kind, credentials.error.entity_id, credentials.error.detail);
  return registration;

/** The composition root: the one place that names a producer and hands it to generic code. */
export async function startObservation(env: NodeJS.ProcessEnv = process.env, options: StartupOptions = {}): Promise<{
  readonly port: number; stop(): Promise<void> }> {
  if (!env.OBSERVATION_DATABASE_URL) throw new Error("OBSERVATION_DATABASE_URL is required");
  const credentials = credentialsFromEnv(env);
  const graders = await readGraders(options.graders_file ?? GRADERS_FILE);
  const registration = graders.ok ? prepareGrading(graders.value, oakridgeProfile, env) : graders;
  if (!registration.ok) throw new Error(`observation cannot start: ${registration.error.kind}: ${registration.error.entity_id}: ${registration.error.detail}`);
  const db = openDatabase(env.OBSERVATION_DATABASE_URL);
  try {
    await migrateEmptyDatabase(db);
    const tenants = producerTenants(credentials, oakridgeProfile.producer);
    const registered = await registerAll(db, tenants, registration.value);
    if (!registered.ok) throw new Error(`observation cannot start: ${registered.error.kind}: ${registered.error.entity_id}: ${registered.error.detail}`);
    console.info("[observation] registered grading definitions", { tenants: tenants.length,
      questions: registration.value.questions.map((question) => `${question.question_id}@${question.question_version}`),
      evaluators: registration.value.evaluators.map((evaluator) => `${evaluator.backend_kind}:${evaluator.evaluator_definition_id}`) });
    const evidence = createEvidencePipeline({ db, collector: oakridgeProfile.evidence, repository: options.repository ?? createGitRepositoryReader() });
    const capability = graderCapability(registration.value);
    const app = createApp({ db, credentials, profile: oakridgeProfile, capture_configuration: registration.value.capture, evidence,
      grader_capability: () => capability });
    const server = Bun.serve({ fetch: app.fetch, hostname: env.OBSERVATION_HOST ?? "127.0.0.1", port: Number(env.OBSERVATION_PORT ?? 8791) });

interface RepositoryChoice { readonly repository_key: string; readonly repository_path: string }
/** The launch input's repositories, as the workflow declares them. */
function launchRepositories(input: JsonValue | null): readonly RepositoryChoice[] {
  const repositories = objectOf(input ?? null)?.repositories;
  if (!Array.isArray(repositories)) return [];
  return repositories.flatMap((entry: JsonValue): RepositoryChoice[] => {
    const repository = objectOf(entry);
    const path = objectOf(repository?.preparation)?.repository_path;
    return typeof repository?.key === "string" && typeof path === "string"
      ? [{ repository_key: repository.key, repository_path: path }] : [];
  });
}

async function repositoryAt(sources: CapturedSources, commit_sha: string): Promise<RepositoryChoice | null> {
  for (const repository of launchRepositories(await sources.readRunInput()))
    if (await sources.repository.hasCommit(repository.repository_path, commit_sha)) return repository;
  return null;

const head_sha = objectOf(revision.body)?.head_sha;
if (typeof head_sha !== "string" || head_sha.length === 0)
  return { waiting: notReady("commit_unavailable", `revision ${revision.revision_id} names no head_sha for its file citations`) };
const repository = await repositoryAt(sources, head_sha);
if (!repository) return { waiting: notReady("repository_unavailable", `no launch repository holds commit ${head_sha}`) };
const references: EvidenceReference[] = [];
for (const [index, { citation, address }] of parsed.entries()) {
  const ref = `citation:${index}`;
  if (!address) { references.push(reported(ref, citation, artifact)); continue; }
  const file = await sources.repository.readFile({ repository_path: repository.repository_path, commit_sha: head_sha, path: address.path });
  if (file.state === "unavailable") return { waiting: notReady("repository_unavailable", file.detail) };
  const located: Omit<RepositoryEvidence, "content" | "is_absent"> = { source: "repository", ref,
    repository_key: repository.repository_key, commit_sha: head_sha, path: address.path, line_range: address.line_range };

