/** One configured grader for one question. Mirrors an entry of `observation/graders.json`. */
export interface GraderEntry {
  readonly runner: string;
  readonly model: string;
  /** Runner-specific instructions: a System One recipe, or a judge rubric. */
  readonly instructions: JsonValue;
  /** What one provider call is expected to cost, for the later per-run budget. */
  readonly estimated_cost_per_call: number;
}
export interface QuestionGraders { readonly question_id: string; readonly graders: readonly GraderEntry[] }
/** `observation/graders.json`: the only place a grader is selected. */
export interface GraderConfiguration { readonly questions: readonly QuestionGraders[] }

/** Carried on every configured evaluator definition for the later budget consumer. */
export interface EvaluatorCostMetadata { readonly estimated_cost_per_call: number }

export type GraderConfigurationErrorKind = "invalid_graders" | "duplicate_question" | "unknown_question"
  | "duplicate_grader" | "unknown_runner" | "invalid_instructions" | "invalid_definition";
export interface GraderConfigurationError {
  readonly operation: "grader_configuration";
  readonly kind: GraderConfigurationErrorKind;
  readonly entity_id: string;
  readonly detail: string;
}
const failure = (kind: GraderConfigurationErrorKind, entity_id: string, detail: string): Result<never, GraderConfigurationError> =>
  err({ operation: "grader_configuration", kind, entity_id, detail });

const graderEntrySchema = z.strictObject({ runner: z.string().min(1), model: z.string().min(1), instructions: z.json(),
  estimated_cost_per_call: z.number().finite().nonnegative() });
const configurationSchema = z.strictObject({ questions: z.array(z.strictObject({ question_id: z.string().min(1),
  graders: z.array(graderEntrySchema).min(1) })).min(1) });

/** Parses graders.json. Unknown fields are refused so a misspelt setting cannot be silently ignored. */
export function parseGraderConfiguration(raw: unknown): Result<GraderConfiguration, GraderConfigurationError> {
  const parsed = configurationSchema.safeParse(raw);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    return failure("invalid_graders", "graders.json", issue ? `${issue.path.join(".") || "/"}: ${issue.message}` : "invalid");
  }
  return ok(parsed.data as GraderConfiguration);
}

/** Every runner the configuration selects, once each. */
export const selectedRunners = (configuration: GraderConfiguration): readonly string[] =>
  [...new Set(configuration.questions.flatMap((question) => question.graders.map((grader) => grader.runner)))];

/** One configured grader becomes one immutable definition. Its identity covers the question,
 * runner, model, instructions and estimated cost, so any edit is a new definition. */
export function configuredEvaluator(question: QuestionDefinition, grader: GraderEntry): Result<EvaluatorDefinition, GraderConfigurationError> {
  const entry = runnerEntry(grader.runner);
  if (!entry) return failure("unknown_runner", grader.runner, `question ${question.question_id} selects a runner that is not retained`);
  const problem = entry.instruction_problem(grader.instructions, question);
  if (problem) return failure("invalid_instructions", `${question.question_id}:${grader.runner}`, problem);
  const instruction_text = canonicalJson(grader.instructions);
  if (!instruction_text.ok) return failure("invalid_instructions", `${question.question_id}:${grader.runner}`, instruction_text.error.detail);
  const config = canonicalDigest(["grader-configuration/v1", question.question_id, question.question_version, grader.runner,
    grader.model, instruction_text.value, grader.estimated_cost_per_call]);
  if (!config.ok) return failure("invalid_definition", `${question.question_id}:${grader.runner}`, config.error.detail);
  const cost_metadata: EvaluatorCostMetadata = { estimated_cost_per_call: grader.estimated_cost_per_call };
  return identified({ kind: entry.kind, backend_kind: grader.runner, provider: entry.provider, model: grader.model,
    instruction_text: instruction_text.value, prompt_digest: instructionDigest(instruction_text.value), config_digest: config.value,
    runtime_revision: entry.runtime_revision, cost_metadata: { ...cost_metadata }, seed: null, attempt_controls: null });
}

/** A registered machine grader, as health and the later lifecycle read it. */
export interface RegisteredGrader {
  readonly runner: string;
  readonly question: QuestionKey;
  readonly evaluator_definition_id: EvaluatorDefinitionId;
}
/** Everything startup registers, and the pins a capture writes until the next restart. */
export interface GradingRegistration {
  readonly questions: readonly QuestionDefinition[];
  readonly evaluators: readonly EvaluatorDefinition[];
  readonly graders: readonly RegisteredGrader[];
  readonly capture: CaptureConfiguration;
}

interface PinnedQuestion { readonly pin: CapturePin; readonly evaluators: readonly EvaluatorDefinition[]; readonly graders: readonly RegisteredGrader[] }

function pinQuestion(question: QuestionDefinition, graders: readonly GraderEntry[], human: EvaluatorDefinition)
  : Result<PinnedQuestion, GraderConfigurationError> {
  const evaluators: EvaluatorDefinition[] = [];
  for (const grader of graders) {
    const evaluator = configuredEvaluator(question, grader);
    if (!evaluator.ok) return evaluator;
    if (evaluators.some((known) => known.evaluator_definition_id === evaluator.value.evaluator_definition_id))
      return failure("duplicate_grader", `${question.question_id}:${grader.runner}`, "the same grader is configured twice");
    evaluators.push(evaluator.value);
  }
  const key: QuestionKey = { question_id: question.question_id, question_version: question.question_version };
  const pinned = [...evaluators, human].map((evaluator) => evaluator.evaluator_definition_id as EvaluatorDefinitionId);
  return ok({ evaluators, pin: { ...key, item_kind: question.item_kind, evaluator_definition_ids: pinned },
    graders: evaluators.map((evaluator) => ({ runner: evaluator.backend_kind, question: key,
      evaluator_definition_id: evaluator.evaluator_definition_id as EvaluatorDefinitionId })) });
}

/**
 * Maps graders.json onto the producer's questions. Every question is pinned with its configured
 * graders and the human evaluator; a question graders.json does not mention is pinned to the human
 * evaluator alone. A configured question the producer does not ask is refused.
 */
export function planRegistration(configuration: GraderConfiguration, questions: readonly QuestionDefinition[])
  : Result<GradingRegistration, GraderConfigurationError> {
  const configured = new Map<string, QuestionGraders>();
  for (const entry of configuration.questions) {
    if (configured.has(entry.question_id)) return failure("duplicate_question", entry.question_id, "a question is configured twice");
    if (!questions.some((question) => question.question_id === entry.question_id))
      return failure("unknown_question", entry.question_id, "the producer asks no question with this id");
    configured.set(entry.question_id, entry);
  }
  const human = humanEvaluator();
  if (!human.ok) return human;
  const pinned: PinnedQuestion[] = [];
  for (const question of questions) {
    const result = pinQuestion(question, configured.get(question.question_id)?.graders ?? [], human.value);
    if (!result.ok) return result;
    pinned.push(result.value);
  }
  const evaluators = [...new Map([...pinned.flatMap((entry) => entry.evaluators), human.value]
    .map((evaluator) => [evaluator.evaluator_definition_id, evaluator])).values()];
  return ok({ questions, evaluators, graders: pinned.flatMap((entry) => entry.graders),
    capture: { pins: pinned.map((entry) => entry.pin) } });
}

/** The only grader selection. Swapping a grader is an edit here and a restart. */
export const GRADERS_FILE = fileURLToPath(new URL("../graders.json", import.meta.url));

export interface StartupError { readonly operation: "startup"; readonly kind: string; readonly entity_id: string; readonly detail: string }
const startupError = (kind: string, entity_id: string, detail: string): Result<never, StartupError> =>
  err({ operation: "startup", kind, entity_id, detail });

/** graders.json, checked against the producer's questions, the retained runners and the service's
 * own environment. Nothing is registered unless every configured grader could run. */
export function prepareGrading(graders: unknown, profile: ProducerProfile, env: NodeJS.ProcessEnv): Result<GradingRegistration, StartupError> {
  const configuration = parseGraderConfiguration(graders);
  if (!configuration.ok) return startupError(configuration.error.kind, configuration.error.entity_id, configuration.error.detail);
  const registration = planRegistration(configuration.value, profile.questions);
  if (!registration.ok) return startupError(registration.error.kind, registration.error.entity_id, registration.error.detail);
  const credentials = requireRunnerCredentials(selectedRunners(configuration.value), env);
  if (!credentials.ok) return startupError(credentials.error.kind, credentials.error.entity_id, credentials.error.detail);
  return registration;

async function readGraders(path: string): Promise<Result<unknown, StartupError>> {
  try { return ok(await Bun.file(path).json()); }
  catch (cause) { return startupError("invalid_graders", path, cause instanceof Error ? cause.message : String(cause)); }
}

async function registerAll(db: Database, tenants: readonly TenantScope[], registration: GradingRegistration): Promise<Result<void, StartupError>> {
  for (const tenant of tenants) {
    const registered = await registerDefinitions(db, tenant, registration);
    if (!registered.ok) return startupError("registration_failed", registered.error.entity_id, registered.error.detail);
  }
  return ok(undefined);
}

export interface StartupOptions {
  readonly graders_file?: string;
  readonly repository?: RepositoryReader;
}

/** The composition root: the one place that names a producer and hands it to generic code. */
export async function startObservation(env: NodeJS.ProcessEnv = process.env, options: StartupOptions = {}): Promise<{
  readonly port: number; stop(): Promise<void> }> {
  if (!env.OBSERVATION_DATABASE_URL) throw new Error("OBSERVATION_DATABASE_URL is required");
  const credentials = credentialsFromEnv(env);
  const graders = await readGraders(options.graders_file ?? GRADERS_FILE);
  const registration = graders.ok ? prepareGrading(graders.value, oakridgeProfile, env) : graders;
  if (!registration.ok) throw new Error(`observation cannot start: ${registration.error.kind}: ${registration.error.entity_id}: ${registration.error.detail}`);
  const db = openDatabase(env.OBSERVATION_DATABASE_URL);
  try {
    await migrateEmptyDatabase(db);
    const tenants = producerTenants(credentials, oakridgeProfile.producer);
    const registered = await registerAll(db, tenants, registration.value);
    if (!registered.ok) throw new Error(`observation cannot start: ${registered.error.kind}: ${registered.error.entity_id}: ${registered.error.detail}`);
    console.info("[observation] registered grading definitions", { tenants: tenants.length,
      questions: registration.value.questions.map((question) => `${question.question_id}@${question.question_version}`),
      evaluators: registration.value.evaluators.map((evaluator) => `${evaluator.backend_kind}:${evaluator.evaluator_definition_id}`) });
    const evidence = createEvidencePipeline({ db, collector: oakridgeProfile.evidence, repository: options.repository ?? createGitRepositoryReader() });
    const capability = graderCapability(registration.value);
    const app = createApp({ db, credentials, profile: oakridgeProfile, capture_configuration: registration.value.capture, evidence,
      grader_capability: () => capability });
    const server = Bun.serve({ fetch: app.fetch, hostname: env.OBSERVATION_HOST ?? "127.0.0.1", port: Number(env.OBSERVATION_PORT ?? 8791) });

/** `core/decision-record.ts:18-31`, a line, or a bare path. Anything else stays as text. */
export function parseFileCitation(ref: string): FileAddress | null {
  const match = /^([^\s:]+)(?::(\d+)(?:-(\d+))?)?$/.exec(ref);
  if (!match?.[1]) return null;
  const start = match[2] ? Number(match[2]) : null;
  const end = match[3] ? Number(match[3]) : start;
  if (start !== null && (start < 1 || end === null || end < start)) return null;
  return { path: match[1], line_range: start === null || end === null ? null : { start, end } };

function lines(content: string, range: LineRange | null): string {
  return range ? content.split("\n").slice(range.start - 1, range.end).join("\n") : content;
}

interface RepositoryChoice { readonly repository_key: string; readonly repository_path: string }
/** The launch input's repositories, as the workflow declares them. */
function launchRepositories(input: JsonValue | null): readonly RepositoryChoice[] {
  const repositories = objectOf(input ?? null)?.repositories;
  if (!Array.isArray(repositories)) return [];
  return repositories.flatMap((entry: JsonValue): RepositoryChoice[] => {
    const repository = objectOf(entry);
    const path = objectOf(repository?.preparation)?.repository_path;
    return typeof repository?.key === "string" && typeof path === "string"
      ? [{ repository_key: repository.key, repository_path: path }] : [];
  });
}

async function repositoryAt(sources: CapturedSources, commit_sha: string): Promise<RepositoryChoice | null> {
  for (const repository of launchRepositories(await sources.readRunInput()))
    if (await sources.repository.hasCommit(repository.repository_path, commit_sha)) return repository;
  return null;
}

type CitationEvidence = { readonly references: readonly EvidenceReference[] } | { readonly waiting: EvidenceCollection };

/** Read every citation. Only a required file lookup that cannot run makes the question wait:
 * an absent file, unparseable ref or empty citation list is itself evidence. */
async function citationEvidence(artifact: SourceArtifact, revision: CapturedRevision, sources: CapturedSources): Promise<CitationEvidence> {
  const citations = citationsOf(artifact.selected_value);
  const parsed = citations.map((citation) => ({ citation, address: citation.kind === "file" ? parseFileCitation(citation.ref) : null }));
  if (!parsed.some(({ address }) => address)) return { references: citations.map((citation, index) => reported(`citation:${index}`, citation, artifact)) };
  const head_sha = objectOf(revision.body)?.head_sha;
  if (typeof head_sha !== "string" || head_sha.length === 0)
    return { waiting: notReady("commit_unavailable", `revision ${revision.revision_id} names no head_sha for its file citations`) };
  const repository = await repositoryAt(sources, head_sha);
  if (!repository) return { waiting: notReady("repository_unavailable", `no launch repository holds commit ${head_sha}`) };
  const references: EvidenceReference[] = [];
  for (const [index, { citation, address }] of parsed.entries()) {
    const ref = `citation:${index}`;
    if (!address) { references.push(reported(ref, citation, artifact)); continue; }
    const file = await sources.repository.readFile({ repository_path: repository.repository_path, commit_sha: head_sha, path: address.path });
    if (file.state === "unavailable") return { waiting: notReady("repository_unavailable", file.detail) };
    const located: Omit<RepositoryEvidence, "content" | "is_absent"> = { source: "repository", ref,
      repository_key: repository.repository_key, commit_sha: head_sha, path: address.path, line_range: address.line_range };
    references.push(file.state === "absent" ? { ...located, is_absent: true, content: null }
      : { ...located, is_absent: false, content: lines(file.content, address.line_range) });
  }
  return { references };

 * Reads files at an exact commit with `git cat-file`, never from a worktree. A readable commit
 * without the path is `absent`, which is evidence; a repository or commit that cannot be read is
 * `unavailable`, which makes the question that needed it wait.
 */
export function createGitRepositoryReader(git: Git = spawnGit): RepositoryReader {
  const hasCommit = async (repository_path: string, commit_sha: string): Promise<boolean> =>
    COMMIT.test(commit_sha) && (await git(repository_path, ["cat-file", "-e", `${commit_sha}^{commit}`]))?.code === 0;
  return {
    hasCommit,
    async readFile({ repository_path, commit_sha, path }: RepositoryFileRequest): Promise<RepositoryFile> {
      if (!await hasCommit(repository_path, commit_sha))
        return { state: "unavailable", detail: `commit ${commit_sha} is not readable in ${repository_path}` };
      if (!isTreePath(path)) return { state: "absent" };
      const object = `${commit_sha}:${path}`;
      const kind = await git(repository_path, ["cat-file", "-t", object]);
      if (!kind) return { state: "unavailable", detail: "git could not be run" };
      if (kind.code !== 0) return { state: "absent" };
      const content = await git(repository_path, ["cat-file", "-p", object]);
      return content?.code === 0 ? { state: "present", content: content.stdout }
        : { state: "unavailable", detail: content?.stderr.trim() || "git could not be run" };

